def first_non_repeated(s):  
    for i, c in enumerate(s):  
        if s.count(c) == 1:  
            return c  
    return None  

tests = [  
    ("aabbcc", None),  
    ("abcabc", "a"),  
    ("abba", None),  
    ("", None),  
    ("a", "a")  
]  

for input_str, expected in tests:  
    result = first_non_repeated(input_str)  
    assert result == expected, f"Failed for {input_str}: expected {expected}, got {result}"
